class Evaluator:
    def __init__(self, expression):
        self.tokens = self.tokenize(expression)
        self.current = 0

    def tokenize(self, expr):
        import re
        token_pattern = re.compile(r'\s*(?:(\d*\.\d+|\d+)|(.+?))')
        return [(m.group(1), m.group(2)) for m in token_pattern.finditer(expr)]

    def parse_expression(self):
        return self.parse_term()

    def parse_term(self):
        result = self.parse_factor()
        while self.current < len(self.tokens):
            token = self.tokens[self.current]
            if token[1] == '+':
                self.current += 1
                result += self.parse_factor()
            elif token[1] == '-':
                self.current += 1
                result -= self.parse_factor()
            else:
                break
        return result

    def parse_factor(self):
        result = self.parse_primary()
        while self.current < len(self.tokens):
            token = self.tokens[self.current]
            if token[1] == '*':
                self.current += 1
                result *= self.parse_primary()
            elif token[1] == '/':
                self.current += 1
                denominator = self.parse_primary()
                if denominator == 0:
                    raise ZeroDivisionError("division by zero")
                result /= denominator
            else:
                break
        return result

    def parse_primary(self):
        token = self.tokens[self.current]
        if token[1] == '(':
            self.current += 1
            result = self.parse_expression()
            if self.current < len(self.tokens) and self.tokens[self.current][1] == ')':
                self.current += 1
            return result
        elif token[0] is not None:
            self.current += 1
            return float(token[0])
        else:
            raise ValueError("Unexpected token")

def evaluate(expr: str) -> float:
    """Evaluate an arithmetic expression using a recursive descent parser."""
    evaluator = Evaluator(expr)
    return evaluator.parse_expression()

