class ArithmeticParser:
    def __init__(self, expression):
        self.expression = expression
        self.index = 0

    def parse(self):
        self.current_number = []
        self.stack = []
        self.operations = []
        self.read_expression()
        return self.evaluate_stack()

    def read_expression(self):
        while self.index < len(self.expression):
            char = self.expression[self.index]

            if char.isdigit() or char == '.':
                self.current_number.append(char)
            elif char in "+-*/":
                if self.current_number:
                    self.stack.append(float(''.join(self.current_number)))
                    self.current_number = []
                self.process_operation(char)
            elif char == '(':
                self.stack.append('(')
            elif char == ')':
                if self.current_number:
                    self.stack.append(float(''.join(self.current_number)))
                    self.current_number = []
                self.resolve_parentheses()
            self.index += 1

        if self.current_number:
            self.stack.append(float(''.join(self.current_number)))

    def process_operation(self, operation):
        while (self.operations and
               self.precedence(self.operations[-1]) >= self.precedence(operation)):
            self.stack.append(self.operations.pop())
        self.operations.append(operation)

    def resolve_parentheses(self):
        while self.operations and self.operations[-1] != '(':
            self.stack.append(self.operations.pop())
        if self.operations and self.operations[-1] == '(':
            self.operations.pop()

    def evaluate_stack(self):
        while self.operations:
            self.stack.append(self.operations.pop())
        return self.calculate_result()

    def calculate_result(self):
        values = []
        while self.stack:
            token = self.stack.pop()
            if isinstance(token, float):
                values.append(token)
            else:
                b = values.pop()
                a = values.pop()
                result = self.apply_operation(a, b, token)
                values.append(result)
        return values[0]

    def apply_operation(self, a, b, operation):
        if operation == '+':
            return a + b
        elif operation == '-':
            return a - b
        elif operation == '*':
            return a * b
        elif operation == '/':
            if b == 0:
                raise ZeroDivisionError("division by zero")
            return a / b

    def precedence(self, operation):
        if operation in ('+', '-'):
            return 1
        if operation in ('*', '/'):
            return 2
        return 0

def evaluate(expr: str) -> float:
    """Evaluate an arithmetic expression using an iterative approach with a stack."""
    parser = ArithmeticParser(expr)
    return parser.parse()

class ArithmeticEvaluator:
    def __init__(self, expression):
        self.expression = expression.replace(' ', '')
        self.position = 0

    def parse(self):
        return self._parse_expression()

    def _parse_expression(self):
        total = self._parse_term()
        while self.position < len(self.expression):
            if self.expression[self.position] == '+':
                self.position += 1
                total += self._parse_term()
            elif self.expression[self.position] == '-':
                self.position += 1
                total -= self._parse_term()
            else:
                break
        return total

    def _parse_term(self):
        total = self._parse_factor()
        while self.position < len(self.expression):
            if self.expression[self.position] == '*':
                self.position += 1
                total *= self._parse_factor()
            elif self.expression[self.position] == '/':
                self.position += 1
                denominator = self._parse_factor()
                if denominator == 0:
                    raise ZeroDivisionError("division by zero")
                total /= denominator
            else:
                break
        return total

    def _parse_factor(self):
        if self.position < len(self.expression) and self.expression[self.position] == '(':
            self.position += 1
            result = self._parse_expression()
            if self.position < len(self.expression) and self.expression[self.position] == ')':
                self.position += 1
            return result
        return self._parse_number()

    def _parse_number(self):
        number_str = ''
        while (self.position < len(self.expression) and 
               (self.expression[self.position].isdigit() or 
                self.expression[self.position] == '.')):
            number_str += self.expression[self.position]
            self.position += 1

        if number_str:
            return float(number_str)
        raise ValueError("Unexpected character found")

def evaluate(expr: str) -> float:
    """Evaluate an arithmetic expression using a recursive descent parser with position tracking."""
    evaluator = ArithmeticEvaluator(expr)
    return evaluator.parse()
